return items.map(item => {
  const data = item.json;
  data.CPL = data.spend / data.actions.find(a => a.action_type === 'lead').value;
  data.CPA = data.spend / data.actions.find(a => a.action_type === 'purchase').value;
  data.ROAS = data.actions.find(a => a.action_type === 'purchase').value / data.spend;
  data.CTR = data.clicks / data.impressions;
  data.CPC = data.spend / data.clicks;
  data.CPM = (data.spend / data.impressions) * 1000;
  data.frequency = data.impressions / data.reach;
  return { json: data };
});

